// A class whose members are all movable.
// The compiler will generate a move constructor and move assignment operator.
class Widget {
private:
    std::string s;
    std::vector<int> v;
public:
    // No user-declared move/copy/destructor here.
    // ... other member functions ...
};

Widget w1;
// Calls the compiler-generated move constructor
Widget w2 = std::move(w1);

Widget w3;
// Calls the compiler-generated move assignment operator
w3 = std::move(w2);
